/* /* */
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>

// Big-number Fibonacci, digits stored little-endian base 10.
int main(int argc, char **argv) {
    long n = argc > 1 ? std::atol(argv[1]) : 0;
    std::vector<int> a(1, 1), b(1, 1);
    for (long i = 0; i < n; i++) {
        std::vector<int> c;
        int carry = 0;
        for (size_t j = 0; j < a.size() || j < b.size() || carry; j++) {
            int s = carry;
            if (j < a.size()) s += a[j];
            if (j < b.size()) s += b[j];
            c.push_back(s % 10);
            carry = s / 10;
        }
        a = b;
        b = c;
    }
    std::string out;
    for (size_t j = a.size(); j > 0; j--) out.push_back((char)(48 + a[j - 1]));
    std::printf("%s\n", out.c_str());
    return 0;
}
